INSERT INTO "public"."ss_child_ai" VALUES (2059848617573117953, 1002, '我今天在学校画了一头蓝色的狮子，老师夸我很有想象力！', '哇！蓝狮子？🦁 那肯定超级酷！它是不是会喷火？快给我讲讲，它长什么样？💙', 5, NULL, -1, '2026-05-30 12:05:55.224', -1, '2026-05-30 12:05:55.224', '0', -1);
