INSERT INTO "public"."ss_parent_emotion_kit" VALUES (1, 1002, '深呼吸放松法', 1, '当感到焦虑时：1. 找一个安静的地方坐下 2. 闭上眼睛 3. 慢慢吸气数到4 4. 屏住呼吸数到4 5. 慢慢呼气数到6 6. 重复3-5次', NULL, 0, '1001', '2026-05-30 01:49:21.639688', NULL, NULL);
INSERT INTO "public"."ss_parent_emotion_kit" VALUES (2, 1002, '情绪颜色画', 2, '当生气时：1. 拿出画笔和纸 2. 用红色画出你的愤怒 3. 慢慢换成蓝色画平静的大海 4. 深呼吸，感受平静', NULL, 0, '1001', '2026-05-30 01:49:21.639688', NULL, NULL);
INSERT INTO "public"."ss_parent_emotion_kit" VALUES (3, 1003, '拥抱充电站', 3, '当难过时：1. 找一个毛绒玩具 2. 给它一个大大的拥抱 3. 告诉它你的感受 4. 想象它在安慰你', NULL, 0, '1001', '2026-05-30 01:49:21.639688', NULL, NULL);
INSERT INTO "public"."ss_parent_emotion_kit" VALUES (4, 1003, '快乐歌单', 4, '当情绪低落时：1. 播放你喜欢的歌 2. 跟着节奏轻轻摇摆 3. 大声唱出来 4. 跳一段自创舞蹈', NULL, 0, '1001', '2026-05-30 01:49:21.639688', NULL, NULL);
